export function ScrollReveal({
  direction = "{{direction}}",
  duration = {{duration}},
  stagger = {{stagger}},
  accent = "{{accent}}",
}) {
  const anim = { up: "mot-rev-up", left: "mot-rev-left", scale: "mot-rev-scale" }[direction];
  const items = ["Card one", "Card two", "Card three"];
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      {items.map((label, i) => (
        <div key={label} className={`item s${i + 1}`} style={{ background: "#fff", border: `1.5px solid ${accent}`, borderRadius: 8, padding: "10px 12px", marginBottom: 8, fontSize: 13, color: "#241430" }}>
          {label}
        </div>
      ))}
      <p style={{ margin: "10px 0 0" }}>Reveals from {direction} as each card enters the viewport &middot; {duration}ms</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .item { animation: ${anim} ${duration}ms ease-out both; }
          .s1 { animation-delay: ${stagger ? 0 : 0}ms; }
          .s2 { animation-delay: ${stagger ? 150 : 0}ms; }
          .s3 { animation-delay: ${stagger ? 300 : 0}ms; }
          @keyframes mot-rev-up { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
          @keyframes mot-rev-left { from { opacity: 0; transform: translateX(-24px); } to { opacity: 1; transform: translateX(0); } }
          @keyframes mot-rev-scale { from { opacity: 0; transform: scale(.85); } to { opacity: 1; transform: scale(1); } }
        }
      `}</style>
    </div>
  );
}
